template.xpath:
/*
 * Stabiler globaler Seitenschutz für alle Fertigungs-Master.
 * Die einzelnen Master werden von parallelen QWeb-Erweiterungen
 * bereitgestellt. Deshalb darf dieser Layer nicht per XPath in
 * deren erzeugte Knoten greifen.
 */
.sab-master-page {
    page-break-before: always !important;
    page-break-after: always !important;
    page-break-inside: avoid !important;
    break-before: page !important;
    break-after: page !important;
    break-inside: avoid !important;
    position: relative;
    overflow: hidden;
    box-sizing: border-box;
}
.sab-master-page table,
.sab-master-page tr,
.sab-master-page td,
.sab-master-page th {
    page-break-inside: avoid !important;
    break-inside: avoid !important;
}
